#!/usr/bin/env bash
# Launcher of the HydroLAKES v1.1 small reservoirs (plan docs/plans/2026-11-08-hl11-small-plan.md): tier runs in 10
# processes, a single-process retry, the 45 km edge pass, the lock, the widening (10 processes) and its lock, the tier
# summary; then the reservoirs without SWBD water go to the SRTM floor (6 processes, retry, lock, summary); coverage last.
# One BLAS / OpenMP thread per process. DO NOT EDIT THIS FILE WHILE IT IS RUNNING.
# Usage: bash 04_Code/scripts/hl11_small_batch.sh
cd "$(dirname "$0")/../.." || exit 1
LOG=05_Results/by_date/2026-11-08/hl11_small_v1/logs; mkdir -p "$LOG"
export PYTHONIOENCODING=utf-8 OPENBLAS_NUM_THREADS=1 OMP_NUM_THREADS=1 MKL_NUM_THREADS=1
run() { .venv/Scripts/python.exe -I 04_Code/scripts/hl11_small_v1.py "$@" 2>&1 | grep --line-buffered -v "^r2 {" | grep --line-buffered -v "/C {'iteration'"; }
N=10
for i in $(seq 1 $N); do run run --part "$i/$N" >> "$LOG/run_${i}of${N}.log" & done; wait
run run >> "$LOG/retry.log"
run retry-edge >> "$LOG/edge.log"
run lock >> "$LOG/lock.log"
for i in $(seq 1 $N); do run widen --part "$i/$N" >> "$LOG/widen_${i}of${N}.log" & done; wait
run widen >> "$LOG/widen_retry.log"
run widen-lock >> "$LOG/widen_lock.log"
run tier-summary >> "$LOG/tier_summary.log"
run floor-list >> "$LOG/floor_list.log"
M=6
for i in $(seq 1 $M); do run floor-run --part "$i/$M" >> "$LOG/floor_${i}of${M}.log" & done; wait
run floor-run >> "$LOG/floor_retry.log"
run floor-lock >> "$LOG/floor_lock.log"
run floor-summary >> "$LOG/floor_summary.log"
run coverage >> "$LOG/coverage.log"
echo "batch finished $(date -Iseconds)" >> "$LOG/batch.log"
